// Structure-of-arrays conversion is intentionally not part of this experiment.
struct Particle {
    float x, y, z;
    float vx, vy, vz;
    float mass;
};

// Each thread updates one target particle using a direct all-pairs loop.
extern "C" __global__ void nbody_step_naive(const Particle* in, Particle* out, int n, float dt) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;

    const float G = 1.0f;
    const float softening = 0.001f;

    float fx = 0.0f;
    float fy = 0.0f;
    float fz = 0.0f;

    // Skip the self interaction without evaluating its arithmetic.
    for (int j = 0; j < i; j++) {
        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float invDist = rsqrtf(distSq);
        float invDist3 = invDist * invDist * invDist;
        float f = (G * in[i].mass * in[j].mass) * invDist3;

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    for (int j = i + 1; j < n; j++) {
        float dx = in[j].x - in[i].x;
        float dy = in[j].y - in[i].y;
        float dz = in[j].z - in[i].z;

        float distSq = dx * dx + dy * dy + dz * dz + softening;
        float invDist = rsqrtf(distSq);
        float invDist3 = invDist * invDist * invDist;
        float f = (G * in[i].mass * in[j].mass) * invDist3;

        fx += f * dx;
        fy += f * dy;
        fz += f * dz;
    }

    // Explicit Euler integration.
    Particle p = in[i];
    p.vx += (fx / p.mass) * dt;
    p.vy += (fy / p.mass) * dt;
    p.vz += (fz / p.mass) * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;

    out[i] = p;
}
